    /**
     * Returns a parent table cell that contains the graphic object.
     *
     * @returns returns null if parent cell doesn't exist.
     *
     * @example
     * ```js
     * // How do I find which table cell holds a drawing in a document?
     *
     * // Useful when you need to add text alongside a shape placed inside a table cell in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = Api.CreateParagraph();
     * let table = Api.CreateTable(3, 3);
     * let tableStyle = doc.GetStyle("Bordered");
     * table.SetStyle(tableStyle);
     * table.SetWidth("percent", 100);
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let drawing = Api.CreateShape("rect", 3212465, 963295, fill, stroke);
     * let cell = table.GetCell(1, 1);
     * cell.GetContent().GetElement(0).AddDrawing(drawing);
     * doc.Push(table);
     * let parentCell = drawing.GetParentTableCell();
     * let cellContent = parentCell.GetContent().GetElement(0);
     * cellContent.AddLineBreak();
     * cellContent.AddText("This is a parent cell");
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiDrawing/Methods/GetParentTableCell/
     */
    GetParentTableCell(): ApiTableCell | null;

    /**
     * Returns the previous inline chart if exists.
     *
     * @returns return null if char if first.
     *
     * @example
     * ```js
     * // How do I access the previous chart and update its gridlines in a document?
     *
     * // Reach back to an earlier chart and assign a custom stroke to its minor horizontal gridlines in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = doc.GetElement(0);
     * let chart = Api.CreateChart("bar3D", [
     * 	[200, 240, 280],
     * 	[250, 260, 280]
     * ], ["Projected Revenue", "Estimated Costs"], [2014, 2015, 2016], 4051300, 2347595, 24);
     * let fill = Api.CreateSolidFill(Api.RGB(51, 51, 51));
     * chart.SetSeriesFill(fill, 0, false);
     * fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * chart.SetSeriesFill(fill, 1, false);
     * chart.SetVerAxisTitle("USD In Hundred Thousands", 10);
     * chart.SetHorAxisTitle("Year", 11);
     * chart.SetLegendPos("bottom");
     * chart.SetShowDataLabels(false, false, true, false);
     * chart.SetTitle("Financial Overview", 13);
     * paragraph.AddDrawing(chart);
     * let copyChart = chart.Copy();
     * paragraph.AddDrawing(copyChart);
     * let prevChart = copyChart.GetPrevChart();
     * let stroke = Api.CreateStroke(1 * 150, Api.CreateSolidFill(Api.RGB(255, 111, 61)));
     * prevChart.SetMinorHorizontalGridlines(stroke);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiChart/Methods/GetPrevChart/
     */
    GetPrevChart(): ApiChart | null;

    /**
     * Returns the previous inline drawing object if exists.
     *
     * @returns returns null if drawing object is first.
     *
     * @example
     * ```js
     * // How do I get the preceding drawing object in a document?
     *
     * // Apply a horizontal flip to the earlier shape in a sequence of drawings in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = doc.GetElement(0);
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let drawing = Api.CreateShape("cube", 3212465, 963295, fill, stroke);
     * paragraph.AddDrawing(drawing);
     * let copyDrawing = drawing.Copy();
     * paragraph.AddDrawing(copyDrawing);
     * let nextDrawing = copyDrawing.GetPrevDrawing();
     * nextDrawing.SetHorFlip(true);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiDrawing/Methods/GetPrevDrawing/
     */
