    GetName(): string;

    /**
     * Returns the next inline drawing object if exists.
     *
     * @returns returns null if drawing object is last.
     *
     * @example
     * ```js
     * // How do I access the drawing that comes after a given shape in a document?
     *
     * // Traverse sibling drawings and modify the properties of the following shape in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = doc.GetElement(0);
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let drawing = Api.CreateShape("cube", 3212465, 963295, fill, stroke);
     * paragraph.AddDrawing(drawing);
     * let copyDrawing = drawing.Copy();
     * paragraph.AddDrawing(copyDrawing);
     * let nextDrawing = drawing.GetNextDrawing();
     * nextDrawing.SetHorFlip(true);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiDrawing/Methods/GetNextDrawing/
     */
    GetNextDrawing(): ApiDrawing | null;

    /**
     * Returns the next inline image if exists.
     *
     * @returns returns null if image is last.
     *
     * @example
     * ```js
     * // How do I access the image that follows another image in a document?
     *
     * // Copy a sibling image by navigating forward through inline images in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = doc.GetElement(0);
     *
     * let image1 = Api.CreateImage(
     * 	'https://static.onlyoffice.com/assets/docs/samples/img/onlyoffice_logo.png',
     * 	60 * 36000, 60 * 36000
     * );
     * paragraph.AddDrawing(image1);
     * paragraph.AddLineBreak();
     *
     * let image2 = Api.CreateImage(
     * 	'https://static.onlyoffice.com/assets/docs/samples/img/presentation_sky.png',
     * 	130 * 36000, 90 * 36000
     * );
     * paragraph.AddDrawing(image2);
     *
     * let nextImage = image1.GetNextImage();
     * let copyImage = nextImage.Copy();
     * paragraph.AddLineBreak();
     * paragraph.AddDrawing(copyImage);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiImage/Methods/GetNextImage/
     */
    GetNextImage(): ApiImage | null;

    /**
     * Returns a parent content control that contains the graphic object.
     *
     * @returns returns null if parent content control doesn't exist.
     *
     * @example
     * ```js
     * // How do I find the content control that wraps a drawing in a document?
     *
     * // Access the enclosing block-level content control to add text alongside a shape in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = Api.CreateParagraph();
     * let blockLvlSdt = Api.CreateBlockLvlSdt();
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let drawing = Api.CreateShape("rect", 3212465, 963295, fill, stroke);
     * paragraph.AddDrawing(drawing);
     * blockLvlSdt.AddElement(paragraph, 0);
     * doc.AddElement(0, blockLvlSdt);
     * let parentContentControl = drawing.GetParentContentControl();
     * parentContentControl.AddText("This is a parent content control.");
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiDrawing/Methods/GetParentContentControl/
     */
    GetParentContentControl(): ApiBlockLvlSdt | null;

    /**
     * Returns a parent paragraph that contains the graphic object.
     *
     * @returns returns null if parent paragraph doesn't exist.
     *
     * @example
     * ```js
     * // How do I find the paragraph that holds a drawing in a document?
     *
     * // Access the enclosing paragraph to append a line break and label text after a shape in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = doc.GetElement(0);
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let drawing = Api.CreateShape("rect", 3212465, 963295, fill, stroke);
     * paragraph.AddDrawing(drawing);
     * let parentParagraph = drawing.GetParentParagraph();
     * parentParagraph.AddLineBreak();
     * parentParagraph.AddText("This is a parent paragraph");
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiDrawing/Methods/GetParentParagraph/
     */
    GetParentParagraph(): ApiParagraph | null;

    /**
     * Returns a parent table that contains the graphic object.
     *
     * @returns returns null if parent table doesn't exist.
     *
     * @example
     * ```js
     * // How do I find the table that holds a drawing in a document?
     *
     * // Access the enclosing table to apply a style after placing a shape inside one of its cells in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = Api.CreateParagraph();
     * let table = Api.CreateTable(3, 3);
     * table.SetWidth("percent", 100);
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let drawing = Api.CreateShape("rect", 3212465, 963295, fill, stroke);
     * paragraph.AddDrawing(drawing);
     * let cell = table.GetCell(1, 1);
     * cell.AddElement(0, paragraph);
     * doc.Push(table);
     * let parentTable = drawing.GetParentTable();
     * let tableStyle = doc.GetStyle("Bordered");
     * parentTable.SetStyle(tableStyle);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiDrawing/Methods/GetParentTable/
     */
    GetParentTable(): ApiTable | null;

    /**
     * Returns a parent table cell that contains the graphic object.
     *
     * @returns returns null if parent cell doesn't exist.
     *
     * @example
     * ```js
     * // How do I find which table cell holds a drawing in a document?
     *
     * // Useful when you need to add text alongside a shape placed inside a table cell in a document.
     *
     * let doc = Api.GetDocument();
     * let paragraph = Api.CreateParagraph();
     * let table = Api.CreateTable(3, 3);
     * let tableStyle = doc.GetStyle("Bordered");
     * table.SetStyle(tableStyle);
     * table.SetWidth("percent", 100);
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let drawing = Api.CreateShape("rect", 3212465, 963295, fill, stroke);
     * let cell = table.GetCell(1, 1);
     * cell.GetContent().GetElement(0).AddDrawing(drawing);
     * doc.Push(table);
     * let parentCell = drawing.GetParentTableCell();
     * let cellContent = parentCell.GetContent().GetElement(0);
     * cellContent.AddLineBreak();
     * cellContent.AddText("This is a parent cell");
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiDrawing/Methods/GetParentTableCell/
     */
    GetParentTableCell(): ApiTableCell | null;

