    /**
     * Sets the paragraph contents justification.
     *
     * @param sJc - The justification type that will be applied to the paragraph contents.
     *
     * @example
     * ```js
     * // How do I apply left, right, center, or justified alignment to paragraphs in a document?
     *
     * // Demonstrate multiple alignment styles side by side to choose the right layout for content.
     *
     * let doc = Api.GetDocument();
     * let myStyleLeft = doc.CreateStyle("My style with left text alignment");
     * let paraPr = myStyleLeft.GetParaPr();
     * paraPr.SetJc("left");
     * let myStyleRight = doc.CreateStyle("My style with right text alignment");
     * paraPr = myStyleRight.GetParaPr();
     * paraPr.SetJc("right");
     * let myStyleCenter = doc.CreateStyle("My style with center text alignment");
     * paraPr = myStyleCenter.GetParaPr();
     * paraPr.SetJc("center");
     * let myStyleBoth = doc.CreateStyle("My style with justify text alignment");
     * paraPr = myStyleBoth.GetParaPr();
     * paraPr.SetJc("both");
     * let paragraph = doc.GetElement(0);
     * paragraph.AddText("This is a paragraph with the text in it aligned by the left side. ");
     * paragraph.AddText("The justification is specified in the paragraph style. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes.");
     * paragraph.SetStyle(myStyleLeft);
     * paragraph = Api.CreateParagraph();
     * paragraph.AddText("This is a paragraph with the text in it aligned by the right side. ");
     * paragraph.AddText("The justification is specified in the paragraph style. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes.");
     * paragraph.SetStyle(myStyleRight);
     * doc.Push(paragraph);
     * paragraph = Api.CreateParagraph();
     * paragraph.AddText("This is a paragraph with the text in it aligned by the center. ");
     * paragraph.AddText("The justification is specified in the paragraph style. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes.");
     * paragraph.SetStyle(myStyleCenter);
     * doc.Push(paragraph);
     * paragraph = Api.CreateParagraph();
     * paragraph.AddText("This is a paragraph with the text in it aligned by both sides (justified). ");
     * paragraph.AddText("The justification is specified in the paragraph style. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * paragraph.AddText("These sentences are used to add lines for demonstrative purposes.");
     * paragraph.SetStyle(myStyleBoth);
     * doc.Push(paragraph);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiParaPr/Methods/SetJc/
     */
    SetJc(sJc: "left" | "right" | "both" | "center"): boolean;

    /**
     * Specifies that when rendering the document using a page view, all lines of the current paragraph are
     * maintained on a single page whenever possible.
     *
     * @param isKeepLines - The true value enables the option to keep lines of the paragraph on a single page.
     *
     * @example
     * ```js
     * // How do I keep all lines of a paragraph together on one page in a document?
     *
     * // Ensure that long paragraphs always start on a new page rather than breaking mid-content.
     *
     * let doc = Api.GetDocument();
     * let myStyle = doc.CreateStyle("My document style");
     * let paraPr = myStyle.GetParaPr();
     * paraPr.SetKeepLines(true);
     * let paragraph = doc.GetElement(0);
     * paragraph.AddText("This is an example of how the paragraph tries to keep lines together. ");
     * paragraph.AddText("Scroll down to the second page to see it.");
     * for (let x = 0; x < 5; ++x) {
     * 	paragraph = Api.CreateParagraph();
     * 	for (let i = 0; i < 10; ++i) {
     * 		paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * 	}
     * 	doc.Push(paragraph);
     * }
     * paragraph = Api.CreateParagraph();
     * paragraph.AddText("The paragraph lines are moved to the next page to keep them together. ");
     * for (let i = 0; i < 10; ++i) {
     * 	paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * }
     * paragraph.SetStyle(myStyle);
     * doc.Push(paragraph);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiParaPr/Methods/SetKeepLines/
     */
    SetKeepLines(isKeepLines: boolean): boolean;

    /**
     * Specifies that when rendering the document using a paginated view, the contents of the current
     * paragraph are at least
     * partly rendered on the same page as the following paragraph whenever possible.
     *
     * @param isKeepNext - The true value enables the option to keep lines of the paragraph on the same page as the
     *   following paragraph.
     *
     * @example
     * ```js
     * // How do I prevent a paragraph from being separated from the next paragraph in a document?
     *
     * // Ensure two consecutive paragraphs always appear together when the page breaks.
     *
     * let doc = Api.GetDocument();
     * let myStyle = doc.CreateStyle("My document style");
     * let paraPr = myStyle.GetParaPr();
     * paraPr.SetKeepNext(true);
     * let paragraph = doc.GetElement(0);
     * paragraph.AddText("This is an example of how the paragraph tries to keep together with the next paragraph. ");
     * paragraph.AddText("Scroll down to the second page to see it. ");
     * for (let x = 0; x < 5; ++x) {
     * 	paragraph = Api.CreateParagraph();
     * 	for (let i = 0; i < 10; ++i) {
     * 		paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * 	}
     * 	paragraph.SetStyle(myStyle);
     * 	doc.Push(paragraph);
     * }
     * paragraph = Api.CreateParagraph();
     * paragraph.AddText("The paragraph lines stay on the same page as the previous paragraph. ");
     * for (let i = 0; i < 10; ++i) {
     * 	paragraph.AddText("These sentences are used to add lines for demonstrative purposes. ");
     * }
     * doc.Push(paragraph);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/ApiParaPr/Methods/SetKeepNext/
     */
    SetKeepNext(isKeepNext: boolean): boolean;

