    /**
     * Returns the core properties interface for the workbook.
     * This method is used to view or modify standard metadata such as title, author, and keywords.
     *
     * @since 9.0.0
     *
     * @example
     * ```js
     * // How do I set or retrieve metadata like creator, subject, and keywords in a spreadsheet?
     *
     * // Store descriptive information about the document itself in a spreadsheet.
     *
     * const worksheet = Api.GetActiveSheet();
     *
     * const core = Api.GetCore();
     * core.SetCategory("Examples");
     * core.SetContentStatus("Final");
     * core.SetCreated(new Date("2000-01-20"));
     * core.SetCreator("John Smith");
     * core.SetDescription("Sample spreadsheet demonstrating ApiCore methods.");
     * core.SetIdentifier("#ID42");
     * core.SetKeywords("Spreadsheet; ApiCore; Metadata");
     * core.SetLanguage("en-US");
     * core.SetLastModifiedBy("Mark Pottato");
     * core.SetLastPrinted(new Date());
     * core.SetModified(new Date("1990-03-10"));
     * core.SetRevision("Rev. C");
     * core.SetSubject("Spreadsheet Metadata Showcase");
     * core.SetTitle("My Spreadsheet Title");
     * core.SetVersion("v9.0");
     *
     * let category = core.GetCategory();
     * let contentStatus = core.GetContentStatus();
     * let createdDate = core.GetCreated().toDateString();
     * let creator = core.GetCreator();
     * let description = core.GetDescription();
     * let identifier = core.GetIdentifier();
     * let keywords = core.GetKeywords();
     * let language = core.GetLanguage();
     * let lastModifiedBy = core.GetLastModifiedBy();
     * let lastPrintedDate = core.GetLastPrinted().toDateString();
     * let lastModifiedDate = core.GetModified().toDateString();
     * let revision = core.GetRevision();
     * let subject = core.GetSubject();
     * let title = core.GetTitle();
     * let version = core.GetVersion();
     *
     * let fill = Api.CreateSolidFill(Api.RGB(100, 50, 200));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * const shape = worksheet.AddShape(
     * 	"rect",
     * 	100 * 36000, 100 * 36000,
     * 	fill, stroke,
     * 	0, 0, 3, 0
     * );
     *
     * let docContent = shape.GetContent();
     * let paragraph = docContent.GetElement(0);
     *
     * paragraph.AddText("Category: " + category + "\n");
     * paragraph.AddText("Content Status: " + contentStatus + "\n");
     * paragraph.AddText("Created: " + createdDate + "\n");
     * paragraph.AddText("Creator: " + creator + "\n");
     * paragraph.AddText("Description: " + description + "\n");
     * paragraph.AddText("Identifier: " + identifier + "\n");
     * paragraph.AddText("Keywords: " + keywords + "\n");
     * paragraph.AddText("Language: " + language + "\n");
     * paragraph.AddText("Last Modified By: " + lastModifiedBy + "\n");
     * paragraph.AddText("Last Printed: " + lastPrintedDate + "\n");
     * paragraph.AddText("Last Modified: " + lastModifiedDate + "\n");
     * paragraph.AddText("Revision: " + revision + "\n");
     * paragraph.AddText("Subject: " + subject + "\n");
     * paragraph.AddText("Title: " + title + "\n");
     * paragraph.AddText("Version: " + version);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/Api/Methods/GetCore/
     */
    GetCore(): ApiCore;

    /**
     * Returns the workbook custom properties.
     *
     * @since 9.0.0
     *
     * @example
     * ```js
     * // How do I store custom key-value data inside a spreadsheet?
     *
     * // Attach extra information of any type to the document itself in a spreadsheet.
     *
     * const worksheet = Api.GetActiveSheet();
     *
     * const customProps = Api.GetCustomProperties();
     * customProps.Add("MyStringProperty", "Hello, Spreadsheet!");
     * customProps.Add("MyNumberProperty", 123.450);
     * customProps.Add("MyDateProperty", new Date("23 November 2023"));
     * customProps.Add("MyBoolProperty", true);
     *
     * let stringValue = customProps.Get("MyStringProperty");
     * let numberValue = customProps.Get("MyNumberProperty");
     * let dateValue = customProps.Get("MyDateProperty");
     * let boolValue = customProps.Get("MyBoolProperty");
     *
     * let fill = Api.CreateSolidFill(Api.RGB(0, 100, 200));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * const shape = worksheet.AddShape(
     * 	"rect",
     * 	100 * 36000, 50 * 36000,
     * 	fill, stroke,
     * 	0, 0, 5, 0
     * );
     *
     * let docContent = shape.GetContent();
     * let paragraph = docContent.GetElement(0);
     * paragraph.AddText("Custom String Property: " + stringValue + "\n");
     * paragraph.AddText("Custom Number Property: " + numberValue + "\n");
     * paragraph.AddText("Custom Date Property: " + dateValue.toDateString() + "\n");
     * paragraph.AddText("Custom Boolean Property: " + boolValue);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/Api/Methods/GetCustomProperties/
     */
    GetCustomProperties(): ApiCustomProperties;

    /**
     * Returns the ApiName object by the range name.
     *
     * @param defName - The range name.
     *
     * @example
     * ```js
     * // How do I find a named range using its label in a spreadsheet?
     *
     * // Resolve a range label to its definition and display the result in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * worksheet.GetRange("A1").SetValue("1");
     * worksheet.GetRange("B1").SetValue("2");
     * Api.AddDefName("numbers", "Sheet1!$A$1:$B$1");
     * let defName = Api.GetDefName("numbers");
     * worksheet.GetRange("A3").SetValue("DefName: " + defName.GetName());
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/Api/Methods/GetDefName/
     */
    GetDefName(defName: string): ApiName;

    /**
     * Returns the document information:
     * **Application** - the application the document has been created with.
     * **CreatedRaw** - the date and time when the file was created.
     * **Created** - the parsed date and time when the file was created.
     * **LastModifiedRaw** - the date and time when the file was last modified.
     * **LastModified** - the parsed date and time when the file was last modified.
     * **LastModifiedBy** - the name of the user who has made the latest change to the document.
     * **Authors** - the persons who has created the file.
     * **Title** - this property allows you to simplify your documents classification.
     * **Tags** - this property allows you to simplify your documents classification.
     * **Subject** - this property allows you to simplify your documents classification.
     * **Comment** - this property allows you to simplify your documents classification.
     *
     * @example
     * ```js
     * // How do I access general document information such as the application name in a spreadsheet?
     *
     * // Retrieve metadata about the current file and write it into a cell in a spreadsheet.
     *
     * let docInfo = Api.GetDocumentInfo();
     * let range = Api.GetActiveSheet().GetRange('A1');
     * range.SetValue('This document has been created with: ' + docInfo.Application);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/Api/Methods/GetDocumentInfo/
     */
    GetDocumentInfo(): object;

