    IsEmpty(): boolean;

    /**
     * Returns the last element of the paragraph.
     *
     * @example
     * ```js
     * // How do I read the content of the final element in a paragraph in a spreadsheet?
     *
     * // Identify which run appears at the end of a paragraph to inspect its text in a spreadsheet.
     *
     * const worksheet = Api.GetActiveSheet();
     * const fill = Api.CreateSolidFill(Api.RGB(140, 100, 120));
     * const stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * const shape = worksheet.AddShape(
     * 	'roundRect',
     * 	Api.MillimetersToEmus(70), Api.MillimetersToEmus(20),
     * 	fill, stroke,
     * 	0, 0, 2, 0
     * );
     * const content = shape.GetContent();
     * const paragraph = content.GetElement(0);
     *
     * const run1 = Api.CreateRun();
     * run1.AddText('First. ');
     * paragraph.AddElement(run1);
     *
     * const run2 = Api.CreateRun();
     * run2.AddText('Last.');
     * paragraph.AddElement(run2);
     *
     * const last = paragraph.Last();
     * worksheet.GetRange('A1').SetValue('Last element text: ' + last.GetText());
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiParagraph/Methods/Last/
     */
    Last(): ParagraphContent;

    /**
     * Adds an element to the current paragraph.
     *
     * @param oElement - The document element which will be added at the current position. Returns false if the oElement
     *   type is not supported by a paragraph.
     * @returns Returns `false` if the type of `oElement` is not supported by paragraph content.
     *
     * @example
     * ```js
     * // How do I add text to the end of an existing paragraph in a spreadsheet?
     *
     * // Extend a paragraph with extra content by inserting a run after all existing elements in a spreadsheet.
     *
     * const worksheet = Api.GetActiveSheet();
     * const fill = Api.CreateSolidFill(Api.RGB(130, 100, 160));
     * const stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * const shape = worksheet.AddShape(
     * 	'roundRect',
     * 	Api.MillimetersToEmus(70), Api.MillimetersToEmus(20),
     * 	fill, stroke,
     * 	0, 0, 2, 0
     * );
     *
     * const content = shape.GetContent();
     * const paragraph = content.GetElement(0);
     * const firstRun = paragraph.GetElement(0);
     * firstRun.AddText('Existing text. ');
     *
     * const run = Api.CreateRun();
     * run.AddText('Pushed text.');
     * paragraph.Push(run);
     *
     * worksheet.GetRange('A1').SetValue('Elements in paragraph: ' + paragraph.GetElementsCount());
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiParagraph/Methods/Push/
     */
    Push(oElement: ParagraphContent): boolean;

    /**
     * Removes all the elements from the current paragraph.
     * <note>When all the elements are removed from the paragraph, a new empty run is automatically
     * created. If you want to add
     * content to this run, use the {@link ApiParagraph#GetElement} method.</note>
     *
     * @example
     * ```js
     * // How do I wipe all content out of a paragraph in a spreadsheet?
     *
     * // Reset a paragraph to empty before refilling it with fresh text in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let shape = worksheet.AddShape("flowChartOnlineStorage", 120 * 36000, 70 * 36000, fill, stroke, 0, 2 * 36000, 0, 3 * 36000);
     * let content = shape.GetContent();
     * let paragraph = content.GetElement(0);
     * let run = Api.CreateRun();
     * run.AddText("This is the first text run in the current paragraph.");
     * paragraph.AddElement(run);
     * paragraph.RemoveAllElements();
     * run = Api.CreateRun();
     * run.AddText("We removed all the paragraph elements and added a new text run inside it.");
     * paragraph.AddElement(run);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiParagraph/Methods/RemoveAllElements/
     */
    RemoveAllElements(): boolean;

    /**
     * Removes an element using the position specified.
     * <note>If the element you remove is the last paragraph element (i.e. all the elements are removed
     * from the paragraph),
     * a new empty run is automatically created. If you want to add
     * content to this run, use the {@link ApiParagraph#GetElement} method.</note>
     *
     * @param nPos - The element position which we want to remove from the paragraph.
     *
     * @example
     * ```js
     * // How do I remove one specific piece of text from a paragraph in a spreadsheet?
     *
     * // Trim unwanted content from a paragraph by targeting the run at a given index in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * let fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let shape = worksheet.AddShape("flowChartOnlineStorage", 120 * 36000, 70 * 36000, fill, stroke, 0, 2 * 36000, 0, 3 * 36000);
     * let content = shape.GetContent();
     * let paragraph = content.GetElement(0);
     * paragraph.RemoveAllElements();
     * let run = Api.CreateRun();
     * run.AddText("This is the first paragraph element. ");
     * paragraph.AddElement(run);
     * run = Api.CreateRun();
     * run.AddText("This is the second paragraph element. ");
     * paragraph.AddElement(run);
     * run = Api.CreateRun();
     * run.AddText("This is the third paragraph element (it will be removed from the paragraph and we will not see it). ");
     * paragraph.AddElement(run);
     * paragraph.AddLineBreak();
     * run = Api.CreateRun();
     * run.AddText("This is the fourth paragraph element - it became the third, because we removed the previous run from the paragraph. ");
     * paragraph.AddElement(run);
     * paragraph.AddLineBreak();
     * run = Api.CreateRun();
     * run.AddText("Please note that line breaks are not counted into paragraph elements!");
     * paragraph.AddElement(run);
     * paragraph.RemoveElement(3);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiParagraph/Methods/RemoveElement/
     */
    RemoveElement(nPos: number): boolean;

