    GetRows(value: string | number): ApiRange | null;

    /**
     * Returns selected drawings from the current sheet.
     *
     * @returns .
     *
     * @example
     * ```js
     * // Access each drawing object when multiple are selected at the same time in a spreadsheet?
     *
     * // Modify properties of every highlighted drawing by looping through them in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * let gradientStop1 = Api.CreateGradientStop(Api.CreateRGBColor(255, 213, 191), 0);
     * let gradientStop2 = Api.CreateGradientStop(Api.CreateRGBColor(255, 111, 61), 100000);
     * let fill = Api.CreateLinearGradientFill([gradientStop1, gradientStop2], 5400000);
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let shape = worksheet.AddShape("flowChartOnlineStorage", 60 * 36000, 35 * 36000, fill, stroke, 0, 2 * 36000, 0, 3 * 36000);
     * gradientStop1 = Api.CreateGradientStop(Api.CreateRGBColor(255, 0, 0), 0);
     * gradientStop2 = Api.CreateGradientStop(Api.CreateRGBColor(255, 0, 255), 100000);
     * fill = Api.CreateLinearGradientFill([gradientStop1, gradientStop2], 5400000);
     * stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let image = worksheet.AddImage("https://static.onlyoffice.com/assets/docs/samples/img/presentation_sky.png", 60 * 36000, 35 * 36000, 10, 2 * 36000, 5, 3 * 36000);
     * shape.Select();
     * image.Select();
     * let shapes = worksheet.GetSelectedDrawings();
     * shapes.forEach(function(shape) {
     * 	shape.SetRotation(45);
     * });
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiWorksheet/Methods/GetSelectedDrawings/
     */
    GetSelectedDrawings(): Drawing[];

    /**
     * Returns selected shapes from the current sheet.
     *
     * @returns .
     *
     * @example
     * ```js
     * // Work with shape objects after a user marks them in the document in a spreadsheet?
     *
     * // Update text and positioning for every selected shape simultaneously in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * let gradientStop1 = Api.CreateGradientStop(Api.CreateRGBColor(255, 213, 191), 0);
     * let gradientStop2 = Api.CreateGradientStop(Api.CreateRGBColor(255, 111, 61), 100000);
     * let fill = Api.CreateLinearGradientFill([gradientStop1, gradientStop2], 5400000);
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * worksheet.AddShape("flowChartOnlineStorage", 60 * 36000, 35 * 36000, fill, stroke, 0, 2 * 36000, 0, 3 * 36000);
     * gradientStop1 = Api.CreateGradientStop(Api.CreateRGBColor(255, 0, 0), 0);
     * gradientStop2 = Api.CreateGradientStop(Api.CreateRGBColor(255, 0, 255), 100000);
     * fill = Api.CreateLinearGradientFill([gradientStop1, gradientStop2], 5400000);
     * stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let shape = worksheet.AddShape("flowChartOnlineStorage", 120 * 36000, 70 * 36000, fill, stroke, 0, 2 * 36000, 0, 3 * 36000);
     * shape.Select();
     * let shapes = worksheet.GetSelectedShapes();
     * if (shapes[0]) {
     * 	let content = shapes[0].GetContent();
     * 	content.RemoveAllElements();
     * 	shapes[0].SetVerticalTextAlign("bottom");
     * 	let paragraph = Api.CreateParagraph();
     * 	paragraph.SetJc("left");
     * 	paragraph.AddText("We removed all elements from the shape and added a new paragraph inside it ");
     * 	paragraph.AddText("aligning it vertically by the bottom.");
     * 	content.Push(paragraph);
     * }
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiWorksheet/Methods/GetSelectedShapes/
     */
    GetSelectedShapes(): ApiShape[];

